   export const RESOLVE_CONFIRM_STEP = 'resolve-confirm';
   export const CLARIFY_ANSWERS_STEP = 'clarify-answers';
   export const LAYOUT_STEPS = ['layout', 'layout-late', 'layout-pass2'] as const;
   No import. The values are the contract (C7).
